1	export interface Item {
2	  readonly type: string;
3	  readonly material?: string;
4	  readonly enchantment?: number;
5	  readonly cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  readonly op: "quote";
10	  readonly items: readonly Item[];
11	}
12	
13	export interface Damage {
14	  readonly itemType: string;
15	  readonly amount: number;
16	}
17	
18	export interface Incident {
19	  readonly cause: string;
20	  readonly damages: readonly Damage[];
21	}
22	
23	export interface ClaimStep {
24	  readonly op: "claim";
25	  readonly policy: number;
26	  readonly incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  readonly yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  readonly customer: Customer;
37	  readonly steps: readonly Step[];
38	}
39	
40	export interface QuoteResult {
41	  readonly premium: number;
42	}
43	
44	export interface ClaimResult {
45	  readonly payout: number;
46	  readonly remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  readonly results: readonly StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
67	  values.reduce((sum, value) => sum + amountOf(value), 0);
68	
69	const itemBasePremiumOf = (item: Item): number =>
70	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
71	
72	const BLOCK_PREMIUM = 60;
73	const BLOCK_SIZE = 3;
74	
75	const itemsGroupedByType = (
76	  items: readonly Item[],
77	): readonly (readonly Item[])[] => [
78	  ...items
79	    .reduce(
80	      (groups, item) =>
81	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
82	      new Map<string, readonly Item[]>(),
83	    )
84	    .values(),
85	];
86	
87	const groupBasePremiumOf = (group: readonly Item[]): number =>
88	  group.length === BLOCK_SIZE
89	    ? BLOCK_PREMIUM
90	    : sumOf(group, itemBasePremiumOf);
91	
92	const CURSED_SURCHARGE_RATE = 0.5;
93	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
94	const HIGH_ENCHANTMENT_THRESHOLD = 5;
95	
96	const cursedSurchargeOf = (item: Item): number =>
97	  item.cursed === true ? itemBasePremiumOf(item) * CURSED_SURCHARGE_RATE : 0;
98	
99	const highEnchantmentSurchargeOf = (item: Item): number =>
100	  item.enchantment === HIGH_ENCHANTMENT_THRESHOLD
101	    ? itemBasePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
102	    : 0;
103	
104	const itemSurchargeOf = (item: Item): number =>
105	  cursedSurchargeOf(item) + highEnchantmentSurchargeOf(item);
106	
107	const policyBasePremiumOf = (items: readonly Item[]): number =>
108	  sumOf(itemsGroupedByType(items), groupBasePremiumOf);
109	
110	const policySurchargeOf = (items: readonly Item[]): number =>
111	  sumOf(items, itemSurchargeOf);
112	
113	const premiumBeforeFeeOf = (items: readonly Item[]): number =>
114	  policyBasePremiumOf(items) + policySurchargeOf(items);
115	
116	const quotePremiumOf = (items: readonly Item[]): number =>
117	  premiumBeforeFeeOf(items) + PROCESSING_FEE;
118	
119	export const runScenario = (scenario: Scenario): ScenarioResult => ({
120	  results: [
121	    { premium: quotePremiumOf((scenario.steps[0] as QuoteStep).items) },
122	  ],
123	});
